@fastapi_app.websocket("/ws")
async def websocket_endpoint(websocket: WebSocket):
    shim = KernelShim("/workspace")
    await shim.handle_websocket(websocket)

@fastapi_app.post("/ast-transform")
async def ast_transform(request: Request):
    """Visual Editor: Bi-directional AST manipulation"""
    data = await request.json()
    # Use internal Node script to parse/transform AST
