<script>
    // --- WebSocket Multiplexer ---
    const ws = new WebSocket(`ws://${window.location.host}/ws`);
    const term = new Terminal({ rows: 10, theme: { background: '#000' } });
    term.open(document.getElementById('terminal'));

    ws.onopen = () => {
        term.writeln('\x1b[32m[Connected to Aetheria Kernel Shim]\x1b[0m');
        term.writeln('Environment: Modal Sandbox (NixOS)');
    };

    ws.onmessage = (event) => {
        const msg = JSON.parse(event.data);
        if (msg.channel === 1) {
            term.write(msg.data);
        } else if (msg.channel === 0) {
            handleControlMessage(msg.data);
        }
    };

    // Terminal Input -> Channel 1
    term.onData(data => {
        ws.send(JSON.stringify({ channel: 1, payload: { data: data } }));
    });

