        term.writeln('\x1b[33m[System] Initiating Google Cloud Run deployment...\x1b[0m');
        ws.send(JSON.stringify({
            channel: 0,
            payload: { type: "deploy" }
        }));
    }

    // --- Handlers ---

    function handleControlMessage(data) {
        // Handle Plan Updates
        if (data.plan) {
            const list = document.getElementById('plan-list');
            list.innerHTML = '';
            data.plan.forEach(step => {
                const div = document.createElement('div');
                div.className = `plan-step ${step.status}`;
                div.innerText = step.task;
                list.appendChild(div);
            });
        } 
        // Handle Deployment
        else if (typeof data === 'string') {
             term.writeln(`\x1b[36m${data}\x1b[0m`);
        }
    }

    // --- Visual Editor (Click Interception) ---
    const iframe = document.getElementById('app-preview');
    // In a real implementation, we would inject a script into the iframe
    // to listen for clicks and postMessage back to the parent.
    window.addEventListener('message', (event) => {
        if (event.data.type === 'click_element') {
            console.log("Visual Edit Triggered:", event.data);
            // Send to AST transformer endpoint
            fetch('/ast-transform', {
                method: 'POST',
                body: JSON.stringify(event.data)
            });
        }
    });
</script>
